    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)

            # A shape is closed if its bounding box contains an enclosed zero.
            outside = set()
            q = []
            for y in range(minr, maxr + 1):
                for x in range(minc, maxc + 1):
                    if (y, x) in cells:
                        continue
                    if y in (minr, maxr) or x in (minc, maxc):
                        outside.add((y, x))
                        q.append((y, x))
            while q:
                y, x = q.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (minr <= ny <= maxr and minc <= nx <= maxc and
                            (ny, nx) not in cells and (ny, nx) not in outside):
                        outside.add((ny, nx))
                        q.append((ny, nx))
            closed = any(
                (y, x) not in cells and (y, x) not in outside
                for y in range(minr, maxr + 1)
                for x in range(minc, maxc + 1)
            )
            objects.append({
                "cells": cells, "color": color, "closed": closed,
                "top": minr, "bottom": maxr
            })

    placed = []
    # Closed shapes rise; open shapes fall. Process in the direction of gravity.
    for closed in (True, False):
        group = [o for o in objects if o["closed"] == closed]
        group.sort(key=lambda o: o["top"] if closed else -o["bottom"])

        for obj in group:
            cells = obj["cells"]
            dy = -1 if closed else 1
            while True:
                shifted = {(y + dy, x) for y, x in cells}
                if any(y < 0 or y >= h for y, x in shifted):
                    break
                if any(shifted & other for other in placed):
                    break
                cells = shifted
            obj["cells"] = cells
            placed.append(cells)

    out = [[0] * w for _ in range(h)]
    for obj in objects:
        for y, x in obj["cells"]:
            out[y][x] = obj["color"]
    return out
